  1	import java.util.Arrays;
  2	import java.util.Objects;
  3	
  4	public final class BucketSort {
  5	
  6	    private static final float MIN_SUPPORTED_VALUE = 0.0f;
  7	    private static final float MAX_SUPPORTED_VALUE = 1.0f;
  8	
  9	    private BucketSort() {
 10	    }
 11	
 12	    public static void sort(float[] values) {
 13	        Objects.requireNonNull(values, "values");
 14	        sortInPlace(values);
 15	    }
 16	
 17	    public static float[] sortedCopy(float[] values) {
 18	        Objects.requireNonNull(values, "values");
 19	
 20	        float[] copy = Arrays.copyOf(values, values.length);
 21	        sortInPlace(copy);
 22	        return copy;
 23	    }
 24	
 25	    private static void sortInPlace(float[] values) {
 26	        if (values.length == 0) {
 27	            return;
 28	        }
 29	
 30	        for (float value : values) {
 31	            validateValue(value);
 32	        }
 33	
 34	        Buckets buckets = new Buckets(values.length);
 35	        buckets.distribute(values);
 36	        buckets.sortEach();
 37	        buckets.writeBack(values);
 38	    }
 39	
 40	    private static void insertionSort(float[] bucket, int size) {
 41	        for (int i = 1; i < size; i++) {
 42	            float currentValue = bucket[i];
 43	            int j = i - 1;
 44	            while (j >= 0 && bucket[j] > currentValue) {
 45	                bucket[j + 1] = bucket[j];
 46	                j--;
 47	            }
 48	            bucket[j + 1] = currentValue;
 49	        }
 50	    }
 51	
 52	    private static int bucketIndexFor(float value, int bucketCount) {
 53	        return (int) (bucketCount * value);
 54	    }
 55	
 56	    private static void validateValue(float value) {
 57	        if (value < MIN_SUPPORTED_VALUE || value >= MAX_SUPPORTED_VALUE) {
 58	            throw new IllegalArgumentException(
 59	                "Bucket sort expects values in the range ["
 60	                    + MIN_SUPPORTED_VALUE
 61	                    + ", "
 62	                    + MAX_SUPPORTED_VALUE
 63	                    + "): "
 64	                    + value
 65	            );
 66	        }
 67	    }
 68	
 69	    private static final class Buckets {
 70	
 71	        private final float[][] valuesByBucket;
 72	        private final int[] sizes;
 73	
 74	        private Buckets(int bucketCount) {
 75	            valuesByBucket = new float[bucketCount][];
 76	            sizes = new int[bucketCount];
 77	
 78	            for (int i = 0; i < bucketCount; i++) {
 79	                valuesByBucket[i] = new float[0];
 80	            }
 81	        }
 82	
 83	        private void distribute(float[] values) {
 84	            for (float value : values) {
 85	                add(value);
 86	            }
 87	        }
 88	
 89	        private void sortEach() {
 90	            for (int i = 0; i < valuesByBucket.length; i++) {
 91	                insertionSort(valuesByBucket[i], sizes[i]);
 92	            }
 93	        }
 94	
 95	        private void writeBack(float[] target) {
 96	            int targetIndex = 0;
 97	            for (int i = 0; i < valuesByBucket.length; i++) {
 98	                int size = sizes[i];
 99	                System.arraycopy(valuesByBucket[i], 0, target, targetIndex, size);
100	                targetIndex += size;
101	            }
102	        }
103	
104	        private void add(float value) {
105	            int bucketIndex = bucketIndexFor(value, valuesByBucket.length);
106	            int size = sizes[bucketIndex];
107	            ensureCapacity(bucketIndex, size + 1);
108	            valuesByBucket[bucketIndex][size] = value;
109	            sizes[bucketIndex] = size + 1;
110	        }
111	
112	        private void ensureCapacity(int bucketIndex, int minCapacity) {
113	            float[] bucket = valuesByBucket[bucketIndex];
114	            if (bucket.length >= minCapacity) {
115	                return;
116	            }
117	
118	            int newCapacity = Math.max(1, bucket.length * 2);
119	            while (newCapacity < minCapacity) {
120	                newCapacity *= 2;
121	            }
122	            valuesByBucket[bucketIndex] = Arrays.copyOf(bucket, newCapacity);
123	        }
124	    }
125	}

  1	import java.util.Arrays;
  2	
  3	public final class BucketSortTest {
  4	
  5	    private BucketSortTest() {
  6	    }
  7	
  8	    public static void main(String[] args) {
  9	        sortsValuesInPlace();
 10	        returnsSortedCopyWithoutMutatingInput();
 11	        returnsDistinctArrayForSortedCopy();
 12	        sortsDuplicateValues();
 13	        sortsValuesNearUpperBound();
 14	        rejectsOutOfRangeValues();
 15	        rejectsNullInput();
 16	        handlesEmptyInput();
 17	    }
 18	
 19	    private static void sortsValuesInPlace() {
 20	        float[] values = {0.42f, 0.32f, 0.23f, 0.52f, 0.25f, 0.47f};
 21	        BucketSort.sort(values);
 22	
 23	        assertArrayEquals(
 24	            new float[]{0.23f, 0.25f, 0.32f, 0.42f, 0.47f, 0.52f},
 25	            values,
 26	            "sort should order values in place"
 27	        );
 28	    }
 29	
 30	    private static void returnsSortedCopyWithoutMutatingInput() {
 31	        float[] original = {0.78f, 0.17f, 0.39f};
 32	        float[] copy = BucketSort.sortedCopy(original);
 33	
 34	        assertArrayEquals(
 35	            new float[]{0.78f, 0.17f, 0.39f},
 36	            original,
 37	            "sortedCopy should not mutate the source array"
 38	        );
 39	        assertArrayEquals(
 40	            new float[]{0.17f, 0.39f, 0.78f},
 41	            copy,
 42	            "sortedCopy should return sorted data"
 43	        );
 44	    }
 45	
 46	    private static void returnsDistinctArrayForSortedCopy() {
 47	        float[] original = {0.31f, 0.21f};
 48	        float[] copy = BucketSort.sortedCopy(original);
 49	
 50	        if (copy == original) {
 51	            throw new AssertionError("sortedCopy should return a distinct array instance");
 52	        }
 53	    }
 54	
 55	    private static void sortsDuplicateValues() {
 56	        float[] values = {0.41f, 0.12f, 0.41f, 0.12f, 0.73f};
 57	        BucketSort.sort(values);
 58	
 59	        assertArrayEquals(
 60	            new float[]{0.12f, 0.12f, 0.41f, 0.41f, 0.73f},
 61	            values,
 62	            "sort should handle duplicate values"
 63	        );
 64	    }
 65	
 66	    private static void sortsValuesNearUpperBound() {
 67	        float[] values = {0.9999f, 0.0001f, 0.5f};
 68	        BucketSort.sort(values);
 69	
 70	        assertArrayEquals(
 71	            new float[]{0.0001f, 0.5f, 0.9999f},
 72	            values,
 73	            "sort should support values close to the upper bound"
 74	        );
 75	    }
 76	
 77	    private static void rejectsOutOfRangeValues() {
 78	        assertThrows(
 79	            IllegalArgumentException.class,
 80	            () -> BucketSort.sort(new float[]{0.5f, 1.0f}),
 81	            "sort should reject values outside [0.0, 1.0)"
 82	        );
 83	    }
 84	
 85	    private static void rejectsNullInput() {
 86	        assertThrows(
 87	            NullPointerException.class,
 88	            () -> BucketSort.sort(null),
 89	            "sort should reject null input"
 90	        );
 91	    }
 92	
 93	    private static void handlesEmptyInput() {
 94	        float[] values = {};
 95	        BucketSort.sort(values);
 96	        assertArrayEquals(new float[]{}, values, "sort should leave empty input unchanged");
 97	    }
 98	
 99	    private static void assertArrayEquals(float[] expected, float[] actual, String message) {
100	        if (!Arrays.equals(expected, actual)) {
101	            throw new AssertionError(
102	                message
103	                    + ". Expected "
104	                    + Arrays.toString(expected)
105	                    + " but was "
106	                    + Arrays.toString(actual)
107	            );
108	        }
109	    }
110	
111	    private static void assertThrows(
112	        Class<? extends Throwable> expectedType,
113	        ThrowingRunnable runnable,
114	        String message
115	    ) {
116	        try {
117	            runnable.run();
118	        } catch (Throwable error) {
119	            if (expectedType.isInstance(error)) {
120	                return;
121	            }
122	            throw new AssertionError(
123	                message + ". Expected " + expectedType.getSimpleName() + " but caught " + error,
124	                error
125	            );
126	        }
127	
128	        throw new AssertionError(
129	            message + ". Expected " + expectedType.getSimpleName() + " but nothing was thrown"
130	        );
131	    }
132	
133	    @FunctionalInterface
134	    private interface ThrowingRunnable {
135	        void run();
136	    }
137	}
